"""Offline checks for the Power BI project in powerbi/ (generated by `python -m dop pbip`).

Checks
  1. Every JSON file parses; every file is UTF-8 without a BOM (CR line endings, which Desktop writes on save,
     are reported as a warning).
  2. Every PBIP/PBIR file (.pbip, .platform, definition.pbir, definition.pbism, version.json, report.json,
     pages.json, page.json, visual.json) validates against the JSON schema named in its "$schema". The schemas
     are vendored in scripts/pbir_schemas and resolved offline through a referencing.Registry keyed by each
     schema's $id (and its published path, which the embedded schemas are referenced by). Every $ref is
     resolved once at start-up; nothing is fetched over the network.
  3. Every Entity/Property (Column, Measure, Aggregation, HierarchyLevel) in every visual.json, page filter and
     drill-through binding resolves to model.bim; queryRefs are unique per visual and formatting selectors point
     at a queryRef of the same visual.
  4. Every relationship column exists in model.bim and in the CSV header, with one data type on both sides, and
     the relationships (active and inactive) are exactly those of POWERBI.md section 3.
  5. Every CSV header in output/csv is a column of its table, with an explicit type in the model and in the
     partition's Table.TransformColumnTypes; the types agree with each other and with POWERBI.md section 2.
  6. Every measure in powerbi/measures.dax is in _Measures with the same expression, and the format strings
     listed in POWERBI.md section 5 are applied.
  7. powerbi/dop_theme.json validates against Microsoft's report theme schema (vendored in scripts/theme_schema),
     is copied unchanged to StaticResources/RegisteredResources and registered in report.json (resourcePackages and
     themeCollection.customTheme); every page background image is a registered image resource.
  8. pages.json pageOrder matches the page folders; page and visual names follow the PBIR naming rules and
     match their folders; drill-through bindings and visual interactions point at existing objects.
  9. Every visual sits inside its page, no two visuals overlap, and content visuals are at least 180 x 90 px.

Usage:  .venv\\Scripts\\python.exe scripts\\check_pbip.py [project folder]      (exit 0 = clean, 1 = problems)
"""
from __future__ import annotations

import csv
import json
import pathlib
import re
import sys

from jsonschema import Draft7Validator
from referencing import Registry
from referencing.jsonschema import DRAFT7

ROOT = pathlib.Path(__file__).resolve().parents[1]
SCHEMA_DIR = pathlib.Path(__file__).resolve().parent / "pbir_schemas"
THEME_SCHEMA_DIR = pathlib.Path(__file__).resolve().parent / "theme_schema"
SCHEMA_BASE = "https://developer.microsoft.com/json-schemas/"
PROJECT = "DOP"
MEASURE_TABLE = "_Measures"
NAME_RE = re.compile(r"^[A-Za-z0-9_-]{1,50}$")
GUID_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")
HEADER_VISUAL = re.compile(r"_h\d+_")           # header strip and title row: exempt from the minimum size
MIN_W, MIN_H = 180, 90
M_TO_TMSL = {"type text": "string", "Int64.Type": "int64", "type number": "double", "type logical": "boolean",
             "type date": "dateTime", "type datetime": "dateTime"}
DOC_TO_TMSL = {"date": "dateTime", "logical": "boolean", "int": "int64", "number": "double"}
AGG_NAMES = {0: "Sum", 1: "Avg", 2: "CountNonNull", 3: "Min", 4: "Max", 5: "Count", 6: "Median",
             7: "StandardDeviation", 8: "Variance"}
_FABRIC = SCHEMA_BASE + "fabric/"
# The schema each file type is documented with, used when a file carries no "$schema"
DOCUMENTED_SCHEMAS = [
    (re.compile(r"[^/]+\.pbip$"), _FABRIC + "pbip/pbipProperties/1.0.0/schema.json"),
    (re.compile(r"(^|/)\.platform$"), _FABRIC + "gitIntegration/platformProperties/2.0.0/schema.json"),
    (re.compile(r"(^|/)definition\.pbir$"), _FABRIC + "item/report/definitionProperties/2.0.0/schema.json"),
    (re.compile(r"(^|/)definition\.pbism$"), _FABRIC + "item/semanticModel/definitionProperties/1.0.0/schema.json"),
    (re.compile(r"/definition/version\.json$"), _FABRIC + "item/report/definition/versionMetadata/1.0.0/schema.json"),
    (re.compile(r"/definition/report\.json$"), _FABRIC + "item/report/definition/report/3.3.0/schema.json"),
    (re.compile(r"/pages/pages\.json$"), _FABRIC + "item/report/definition/pagesMetadata/1.1.0/schema.json"),
    (re.compile(r"/pages/[^/]+/page\.json$"), _FABRIC + "item/report/definition/page/2.1.0/schema.json"),
    (re.compile(r"/visuals/[^/]+/visual\.json$"), _FABRIC + "item/report/definition/visualContainer/2.12.0/schema.json"),
]


# ----------------------------------------------------------------------------------------------------------------
# Schemas
# ----------------------------------------------------------------------------------------------------------------

def _no_network(uri: str):
    raise LookupError(f"schema {uri} is not vendored in scripts/pbir_schemas (network access is disabled)")


def _refs(node):
    if isinstance(node, dict):
        ref = node.get("$ref")
        if isinstance(ref, str):
            yield ref
        for value in node.values():
            yield from _refs(value)
    elif isinstance(node, list):
        for value in node:
            yield from _refs(value)


def load_schemas(problems: list[str]) -> tuple[Registry, dict[str, dict]]:
    """Registry of the vendored schemas keyed by $id and by published path; every $ref resolved once."""
    docs: dict[str, dict] = {}
    for path in sorted(SCHEMA_DIR.rglob("*.json")):
        doc = json.loads(path.read_text(encoding="utf-8"))
        Draft7Validator.check_schema(doc)
        for uri in {SCHEMA_BASE + path.relative_to(SCHEMA_DIR).as_posix(), doc.get("$id")} - {None}:
            docs[uri] = doc
    registry = Registry(retrieve=_no_network).with_resources(
        (uri, DRAFT7.create_resource(doc)) for uri, doc in docs.items())
    for uri, doc in docs.items():
        resolver = registry.resolver(base_uri=uri)
        for ref in sorted(set(_refs(doc))):
            try:
                resolver.lookup(ref)
            except Exception as exc:                     # noqa: BLE001 - report every unresolvable reference
                problems.append(f"schema {uri}: $ref {ref!r} does not resolve ({type(exc).__name__})")
    return registry, docs


def schema_for(url: str, docs: dict[str, dict], warnings: list[str], where: str) -> str | None:
    """The vendored schema for a $schema URL. An unknown version of a known schema family (for example one written
    by a newer Desktop) is checked against the newest vendored version of the same major version, with a warning."""
    if url in docs:
        return url
    m = re.match(r"^(.*)/(\d+)\.(\d+)\.(\d+)/(schema[^/]*\.json)$", url or "")
    if not m:
        return None
    same_major = []
    for known in docs:
        k = re.match(r"^(.*)/(\d+)\.(\d+)\.(\d+)/(schema[^/]*\.json)$", known)
        if k and k.group(1) == m.group(1) and k.group(2) == m.group(2) and k.group(5) == m.group(5):
            same_major.append((tuple(int(x) for x in k.group(2, 3, 4)), known))
    if not same_major:
        return None
    newest = max(same_major)[1]
    warnings.append(f"{where}: $schema {url} is not vendored; checked against {newest}")
    return newest


# ----------------------------------------------------------------------------------------------------------------
# Inputs
# ----------------------------------------------------------------------------------------------------------------

def csv_headers(csv_dir: pathlib.Path) -> dict[str, list[str]]:
    out = {}
    for path in sorted(csv_dir.glob("*.csv")):
        with path.open(encoding="utf-8", newline="") as fh:
            out[path.stem] = next(csv.reader(fh))
    return out


def dax_measures(text: str) -> dict[str, str]:
    """MEASURE name -> expression from measures.dax, read independently of the generator's parser."""
    define = text.split("\nEVALUATE", 1)[0]
    out: dict[str, str] = {}
    parts = re.split(r"(?m)^[ \t]*MEASURE[ \t]+'_Measures'\[", define)
    for part in parts[1:]:
        name, _, rest = part.partition("]")
        body = rest.split("=", 1)[1]
        lines = body.split("\n")
        while lines and (not lines[-1].strip() or lines[-1].strip().startswith("//")):
            lines.pop()
        if name in out:
            out[name + " (duplicate)"] = ""
        out[name] = " ".join(" ".join(lines).split())
    return out


def doc_section(doc: str, number: int) -> str:
    m = re.search(rf"(?ms)^## {number}\. .*?(?=^## {number + 1}\. |\Z)", doc)
    return m.group(0) if m else ""


def doc_relationships(doc: str) -> set[tuple[str, str, str, str, bool]]:
    rows = re.findall(r"(?m)^\|\s*`(\w+)\[(\w+)\]`\s*\|\s*`(\w+)\[(\w+)\]`\s*\|[^|\n]*\|[^|\n]*\|\s*\**(Yes|No)\**\s*\|",
                      doc_section(doc, 3))
    return {(a, b, c, d, e == "Yes") for a, b, c, d, e in rows}


def doc_types(doc: str) -> dict[str, dict[str, str]]:
    """POWERBI.md section 2: fnLoadCsv(name, {dates}, {logicals}, {whole numbers}, {decimals}) per table."""
    out: dict[str, dict[str, str]] = {}
    pattern = re.compile(r'fnLoadCsv\(\s*"(\w+)"\s*,\s*\{([^}]*)\}\s*,\s*\{([^}]*)\}\s*,\s*\{([^}]*)\}\s*,'
                         r'\s*\{([^}]*)\}\s*\)', re.S)
    for m in pattern.finditer(doc_section(doc, 2)):
        types = out.setdefault(m.group(1), {})
        for kind, names in zip(("date", "logical", "int", "number"), m.groups()[1:]):
            for n in re.findall(r'"([^"]+)"', names):
                types[n] = kind
    return out


def doc_formats(doc: str) -> dict[str, list[str]]:
    """POWERBI.md section 5 format table: format string -> listed measure names (prose items are skipped)."""
    out = {}
    for fmt, names in re.findall(r"(?m)^\|\s*`([^`]+)`\s*\|\s*([^|\n]+?)\s*\|\s*$", doc_section(doc, 5)):
        out[fmt] = [n.strip() for n in names.split(",")]
    return out


# ----------------------------------------------------------------------------------------------------------------
# Field references
# ----------------------------------------------------------------------------------------------------------------

def field_refs(node, aliases=None, path="$"):
    """Yield (kind, entity, property, path) for every Column, Measure and HierarchyLevel reference."""
    aliases = aliases or {}
    if isinstance(node, dict):
        if isinstance(node.get("From"), list):
            aliases = dict(aliases)
            aliases.update({f["Name"]: f.get("Entity") for f in node["From"] if isinstance(f, dict) and "Name" in f})
        for kind in ("Column", "Measure"):
            ref = node.get(kind)
            if isinstance(ref, dict) and "Property" in ref and isinstance(ref.get("Expression"), dict):
                source = ref["Expression"].get("SourceRef", {})
                yield kind, source.get("Entity") or aliases.get(source.get("Source")), ref["Property"], path
        level = node.get("HierarchyLevel")
        if isinstance(level, dict):
            hierarchy = level.get("Expression", {}).get("Hierarchy", {})
            source = hierarchy.get("Expression", {}).get("SourceRef", {})
            yield ("HierarchyLevel", source.get("Entity") or aliases.get(source.get("Source")),
                   f"{hierarchy.get('Hierarchy')}/{level.get('Level')}", path)
        for key, value in node.items():
            yield from field_refs(value, aliases, f"{path}.{key}")
    elif isinstance(node, list):
        for i, value in enumerate(node):
            yield from field_refs(value, aliases, f"{path}[{i}]")


def expected_query_ref(field: dict) -> str | None:
    for kind in ("Column", "Measure"):
        if kind in field:
            ref = field[kind]
            return f"{ref['Expression']['SourceRef'].get('Entity')}.{ref['Property']}"
    if "Aggregation" in field:
        inner = expected_query_ref(field["Aggregation"]["Expression"])
        return f"{AGG_NAMES.get(field['Aggregation'].get('Function'), '?')}({inner})" if inner else None
    return None


def selectors(node):
    if isinstance(node, dict):
        sel = node.get("selector")
        if isinstance(sel, dict) and isinstance(sel.get("metadata"), str):
            yield sel["metadata"]
        for value in node.values():
            yield from selectors(value)
    elif isinstance(node, list):
        for value in node:
            yield from selectors(value)


def theme_problems(theme_path: pathlib.Path) -> list[str]:
    """The theme against Microsoft's report theme schema (vendored in scripts/theme_schema, newest version). The
    schema types every visual's formatting objects except the "*" (all visuals) block, so that block is also checked
    as if it were a line chart's, which has the same container objects (background, border, dropShadow, title)."""
    files = sorted(THEME_SCHEMA_DIR.glob("reportThemeSchema-*.json"),
                   key=lambda p: tuple(int(n) for n in re.findall(r"\d+", p.stem)))
    if not files:
        return [f"{THEME_SCHEMA_DIR.name}: no reportThemeSchema-*.json to check the theme against"]
    validator = Draft7Validator(json.loads(files[-1].read_text(encoding="utf-8")))
    theme = json.loads(theme_path.read_text(encoding="utf-8"))
    docs = [("", theme)]
    generic = theme.get("visualStyles", {}).get("*", {}).get("*")
    if generic:
        docs.append(("visualStyles/*/* checked as lineChart: ",
                     {"name": theme.get("name", ""), "visualStyles": {"lineChart": {"*": generic}}}))
    return [f"powerbi/dop_theme.json: {prefix}{'/'.join(map(str, e.path)) or '(root)'}: {e.message[:200]} "
            f"({files[-1].name})"
            for prefix, doc in docs for e in validator.iter_errors(doc)]


# ----------------------------------------------------------------------------------------------------------------
# Checks
# ----------------------------------------------------------------------------------------------------------------

def run_checks(project: pathlib.Path = ROOT / "powerbi", root: pathlib.Path = ROOT):
    """Return (problems, warnings, stats) for the project folder that holds DOP.pbip."""
    problems: list[str] = []
    warnings: list[str] = []
    rel = lambda p: p.relative_to(project).as_posix()           # noqa: E731
    report_dir = project / f"{PROJECT}.Report"
    model_dir = project / f"{PROJECT}.SemanticModel"
    for required in (project / f"{PROJECT}.pbip", model_dir / "model.bim", model_dir / "definition.pbism",
                     report_dir / "definition.pbir", report_dir / "definition" / "report.json"):
        if not required.is_file():
            problems.append(f"missing {required}")
    if problems:
        return problems, warnings, {}
    if (model_dir / "definition").exists():
        problems.append("DOP.SemanticModel has both model.bim and a TMDL definition folder")

    # 1. parse, encoding --------------------------------------------------------------------------------------
    docs_json: dict[pathlib.Path, object] = {}
    for path in sorted(p for p in project.rglob("*") if p.is_file() and ".pbi" not in p.parts):
        data = path.read_bytes()
        if data.startswith(b"\xef\xbb\xbf"):
            problems.append(f"{rel(path)}: starts with a UTF-8 byte order mark")
        if b"\r" in data:      # Desktop saves with CRLF; .gitattributes normalises to LF on commit
            warnings.append(f"{rel(path)}: has CR line endings (the generator writes LF)")
        try:
            data.decode("utf-8")
        except UnicodeDecodeError:
            problems.append(f"{rel(path)}: is not UTF-8")
            continue
        if path.suffix in (".json", ".pbir", ".pbism", ".pbip", ".bim") or path.name == ".platform":
            try:
                docs_json[path] = json.loads(data.decode("utf-8"))
            except json.JSONDecodeError as exc:
                problems.append(f"{rel(path)}: does not parse as JSON ({exc})")
    if problems:
        return problems, warnings, {}

    # 2. schemas ----------------------------------------------------------------------------------------------
    registry, schemas = load_schemas(problems)
    pbir_files = [p for p in docs_json if p.suffix in (".pbip", ".pbir", ".pbism") or p.name == ".platform"
                  or (p.suffix == ".json" and report_dir / "definition" in p.parents)]
    if sum(1 for p in pbir_files if p.name == ".platform") != 2:
        problems.append("expected a .platform file in both the report and the semantic model folders")
    validated = 0
    for path in sorted(pbir_files):
        instance = docs_json[path]
        url = instance.get("$schema") if isinstance(instance, dict) else None
        if not url:
            url = next((s for pattern, s in DOCUMENTED_SCHEMAS if pattern.search(rel(path))), None)
            if url is None:
                problems.append(f"{rel(path)}: no $schema, and no documented schema for this file type")
                continue
            warnings.append(f"{rel(path)}: no $schema; checked against the documented {url}")
        uri = schema_for(url, schemas, warnings, rel(path))
        if uri is None:
            problems.append(f"{rel(path)}: $schema {url} is not a known schema")
            continue
        checked = dict(instance, **{"$schema": uri}) if uri != url else instance
        errors = sorted(Draft7Validator(schemas[uri], registry=registry).iter_errors(checked),
                        key=lambda e: list(e.absolute_path))
        for err in errors[:10]:
            where = "/".join(str(x) for x in err.absolute_path) or "(root)"
            problems.append(f"{rel(path)}: schema: {where}: {err.message[:300]}")
        validated += 1

    # model ---------------------------------------------------------------------------------------------------
    model = docs_json[model_dir / "model.bim"]["model"]
    tables = {t["name"]: t for t in model.get("tables", [])}
    columns = {t: {c["name"]: c for c in tdef.get("columns", [])} for t, tdef in tables.items()}
    measures = {m["name"]: (t, m) for t, tdef in tables.items() for m in tdef.get("measures", [])}
    hierarchies = {(t, h["name"]): [lvl["name"] for lvl in h.get("levels", [])]
                   for t, tdef in tables.items() for h in tdef.get("hierarchies", [])}
    level_cols = {(t, h["name"], lvl["name"]): lvl.get("column")
                  for t, tdef in tables.items() for h in tdef.get("hierarchies", []) for lvl in h.get("levels", [])}
    if docs_json[model_dir / "model.bim"].get("compatibilityLevel", 0) < 1567:
        problems.append("model.bim: compatibilityLevel is below 1567")
    if model.get("defaultPowerBIDataSourceVersion") != "powerBI_V3":
        problems.append("model.bim: defaultPowerBIDataSourceVersion must be powerBI_V3")
    annotations = {a["name"]: a["value"] for a in model.get("annotations", [])}
    if annotations.get("__PBI_TimeIntelligenceEnabled") != "0":
        problems.append("model.bim: annotation __PBI_TimeIntelligenceEnabled must be \"0\"")
    expressions = {e["name"]: e for e in model.get("expressions", [])}
    csv_folder = expressions.get("CsvFolder", {}).get("expression", "")
    if isinstance(csv_folder, list):
        csv_folder = "\n".join(csv_folder)
    if "IsParameterQuery=true" not in csv_folder or 'Type="Text"' not in csv_folder:
        problems.append("model.bim: CsvFolder must be a Text parameter query (meta IsParameterQuery=true)")
    date_table = tables.get("dim_date", {})
    if date_table.get("dataCategory") != "Time" or not columns.get("dim_date", {}).get("date", {}).get("isKey"):
        problems.append("model.bim: dim_date is not marked as the date table (dataCategory Time, date isKey)")
    for t, cols in columns.items():
        for c in cols.values():
            if c.get("sortByColumn") and c["sortByColumn"] not in cols:
                problems.append(f"model.bim: {t}[{c['name']}] sorts by missing column {c['sortByColumn']}")
            if c["name"].endswith(("_id", "_code", "_key")) and c.get("summarizeBy") != "none":
                problems.append(f"model.bim: key or code column {t}[{c['name']}] must have summarizeBy none")
    for (t, h, lvl), column in level_cols.items():
        if column not in columns.get(t, {}):
            problems.append(f"model.bim: hierarchy {t}/{h} level {lvl} uses missing column {column}")
    mt = tables.get(MEASURE_TABLE)
    if not mt or len(mt.get("columns", [])) != 1 or not mt["columns"][0].get("isHidden"):
        problems.append("model.bim: _Measures must have exactly one hidden column")

    # 5. CSV headers and types --------------------------------------------------------------------------------
    headers = csv_headers(root / "output" / "csv")
    doc_text = (root / "POWERBI.md").read_text(encoding="utf-8")
    documented = doc_types(doc_text)
    if len(headers) != 22:
        problems.append(f"expected 22 CSV tables in output/csv, found {len(headers)}")
    typed_columns = 0
    for table, header in headers.items():
        if table not in tables:
            problems.append(f"model.bim: no table for output/csv/{table}.csv")
            continue
        partition = tables[table].get("partitions", [{}])[0].get("source", {})
        m_code = partition.get("expression", "")
        m_code = "\n".join(m_code) if isinstance(m_code, list) else m_code
        if f'File.Contents(CsvFolder & "\\{table}.csv")' not in m_code:
            problems.append(f"{table}: partition does not read CsvFolder & \"\\{table}.csv\"")
        if '[Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]' not in m_code or \
                "Table.PromoteHeaders(" not in m_code or "[PromoteAllScalars=true]" not in m_code:
            problems.append(f"{table}: partition must use Csv.Document (comma, UTF-8, QuoteStyle.Csv) and "
                            "Table.PromoteHeaders with PromoteAllScalars=true")
        steps = re.findall(r"Table\.TransformColumnTypes\((\w+),\s*\{(.*?)\n\s*\}", m_code, re.S)
        m_types: dict[str, str] = {}
        for _, body in steps:
            for name, m_type in re.findall(r'\{"([^"]+)",\s*(type \w+|Int64\.Type)\}', body):
                m_types[name] = m_type                  # later steps (datetime -> date) win
        first = dict(re.findall(r'\{"([^"]+)",\s*(type \w+|Int64\.Type)\}', steps[0][1])) if steps else {}
        added = set(re.findall(r'Table\.AddColumn\(\w+,\s*"([^"]+)"', m_code))
        for column in header:
            model_col = columns[table].get(column)
            if not model_col or model_col.get("sourceColumn") != column:
                problems.append(f"{table}: CSV column {column} is not a model column")
                continue
            if column not in first:
                problems.append(f"{table}: CSV column {column} is not typed in Table.TransformColumnTypes")
                continue
            if M_TO_TMSL.get(m_types[column]) != model_col.get("dataType"):
                problems.append(f"{table}[{column}]: Power Query type {m_types[column]} does not match model "
                                f"dataType {model_col.get('dataType')}")
            expected = DOC_TO_TMSL.get(documented.get(table, {}).get(column), "string")
            if table in documented and model_col.get("dataType") != expected:
                problems.append(f"{table}[{column}]: model dataType {model_col.get('dataType')} differs from "
                                f"POWERBI.md section 2 ({expected})")
            typed_columns += 1
        for column in documented.get(table, {}):
            if column not in header:
                problems.append(f"POWERBI.md section 2 types {table}[{column}], which is not in the CSV header")
        for column, cdef in columns[table].items():
            if column not in header and column not in added:
                problems.append(f"{table}[{column}] is neither a CSV column nor added in Power Query")
    for table in documented:
        if table not in headers:
            problems.append(f"POWERBI.md section 2 loads {table}, which is not in output/csv")

    # 4. relationships ----------------------------------------------------------------------------------------
    model_rels = set()
    for r in model.get("relationships", []):
        ends = ((r.get("fromTable"), r.get("fromColumn")), (r.get("toTable"), r.get("toColumn")))
        for t, c in ends:
            if c not in columns.get(t, {}):
                problems.append(f"relationship {r.get('name')}: {t}[{c}] is not in model.bim")
            elif t in headers and c not in headers[t]:
                problems.append(f"relationship {r.get('name')}: {t}[{c}] is not in output/csv/{t}.csv")
        types = {columns.get(t, {}).get(c, {}).get("dataType") for t, c in ends}
        if len(types) != 1:
            problems.append(f"relationship {ends}: data types differ {sorted(map(str, types))}")
        model_rels.add((ends[0][0], ends[0][1], ends[1][0], ends[1][1], r.get("isActive", True)))
    documented_rels = doc_relationships(doc_text)
    for missing in sorted(documented_rels - model_rels):
        problems.append(f"relationship in POWERBI.md section 3 missing from model.bim: {missing}")
    for extra in sorted(model_rels - documented_rels):
        problems.append(f"relationship in model.bim not in POWERBI.md section 3: {extra}")

    # 6. measures ---------------------------------------------------------------------------------------------
    source = dax_measures((root / "powerbi" / "measures.dax").read_text(encoding="utf-8"))
    for name, expression in source.items():
        if name.endswith(" (duplicate)"):
            problems.append(f"measures.dax: [{name[:-12]}] is defined twice")
        elif name not in measures:
            problems.append(f"measure [{name}] from measures.dax is not in _Measures")
        else:
            table, m = measures[name]
            body = m["expression"] if isinstance(m["expression"], str) else "\n".join(m["expression"])
            if table != MEASURE_TABLE:
                problems.append(f"measure [{name}] is on table {table}, not {MEASURE_TABLE}")
            if " ".join(body.split()) != expression:
                problems.append(f"measure [{name}]: expression differs from measures.dax")
    for name in measures:
        if name not in source:
            problems.append(f"measure [{name}] in model.bim is not in measures.dax")
    for fmt, names in doc_formats(doc_text).items():
        for name in names:
            if name in measures and measures[name][1].get("formatString") != fmt:
                problems.append(f"measure [{name}]: formatString {measures[name][1].get('formatString')!r}, "
                                f"POWERBI.md section 5 says {fmt!r}")

    # 7. theme ------------------------------------------------------------------------------------------------
    report = docs_json[report_dir / "definition" / "report.json"]
    theme_src = root / "powerbi" / "dop_theme.json"
    custom = report.get("themeCollection", {}).get("customTheme", {})
    theme_name = custom.get("name")
    registered = [i for pkg in report.get("resourcePackages", []) if pkg.get("type") == "RegisteredResources"
                  for i in pkg.get("items", [])]
    resources_dir = report_dir / "StaticResources" / "RegisteredResources"
    if custom.get("type") != "RegisteredResources" or not theme_name:
        problems.append("report.json: themeCollection.customTheme is not a RegisteredResources theme")
    elif not (resources_dir / theme_name).is_file():
        problems.append(f"theme {theme_name} is not in StaticResources/RegisteredResources")
    elif (resources_dir / theme_name).read_bytes() != theme_src.read_bytes():
        problems.append(f"StaticResources/RegisteredResources/{theme_name} differs from powerbi/dop_theme.json")
    if not any(i.get("name") == theme_name and i.get("path") == theme_name and i.get("type") == "CustomTheme"
               for i in registered):
        problems.append("report.json: the custom theme is not listed in resourcePackages (RegisteredResources)")
    if resources_dir.is_dir():
        for f in resources_dir.iterdir():
            if not any(i.get("path") == f.name for i in registered):
                problems.append(f"StaticResources/RegisteredResources/{f.name} has no entry in report.json")
    problems.extend(theme_problems(theme_src))
    images = {i.get("name") for i in registered if i.get("type") == "Image" and (resources_dir / i.get("path", "")).is_file()}
    for page_json in sorted((report_dir / "definition" / "pages").glob("*/page.json")):
        for bg in docs_json.get(page_json, {}).get("objects", {}).get("background", []):
            item = (bg.get("properties", {}).get("image", {}).get("image", {}).get("url", {}).get("expr", {})
                    .get("ResourcePackageItem", {}))
            if item and (item.get("PackageName") != "RegisteredResources" or item.get("ItemName") not in images):
                problems.append(f"{rel(page_json)}: background image {item.get('ItemName')!r} is not a registered "
                                "image in StaticResources/RegisteredResources")

    # project wiring ------------------------------------------------------------------------------------------
    pbip = docs_json[project / f"{PROJECT}.pbip"]
    for artifact in pbip.get("artifacts", []):
        target = artifact.get("report", {}).get("path", "")
        if "\\" in target or target.startswith("/") or not (project / target / "definition.pbir").is_file():
            problems.append(f"{PROJECT}.pbip: report path {target!r} is not a relative path to a report folder")
    by_path = docs_json[report_dir / "definition.pbir"].get("datasetReference", {}).get("byPath", {}).get("path", "")
    if "\\" in by_path or not (report_dir / by_path / "definition.pbism").is_file():
        problems.append(f"definition.pbir: byPath {by_path!r} does not reach a semantic model folder")
    if docs_json[report_dir / "definition" / "version.json"].get("version") != "2.0.0":
        problems.append("version.json: version must be \"2.0.0\" (PBIR)")
    logical_ids = [docs_json[p].get("config", {}).get("logicalId", "") for p in docs_json if p.name == ".platform"]
    for lid in logical_ids:
        if not GUID_RE.match(lid):
            problems.append(f".platform: logicalId {lid!r} is not a GUID")
    if len(set(logical_ids)) != len(logical_ids):
        problems.append(".platform: logicalId values are not unique")

    # 8, 3, 9. pages and visuals ------------------------------------------------------------------------------
    pages_dir = report_dir / "definition" / "pages"
    pages_meta = docs_json.get(pages_dir / "pages.json", {})
    folders = sorted(p.name for p in pages_dir.iterdir() if p.is_dir())
    order = pages_meta.get("pageOrder", [])
    if sorted(order) != folders or len(set(order)) != len(order):
        problems.append(f"pages.json: pageOrder {order} does not match the page folders {folders}")
    if pages_meta.get("activePageName") not in order:
        problems.append("pages.json: activePageName is not in pageOrder")
    bindings: list[str] = []
    n_visuals = n_refs = 0
    for folder in folders:
        page_path = pages_dir / folder / "page.json"
        page = docs_json.get(page_path)
        if not isinstance(page, dict):
            problems.append(f"page folder {folder} has no page.json")
            continue
        if page.get("name") != folder or not NAME_RE.match(folder):
            problems.append(f"{rel(page_path)}: name {page.get('name')!r} must equal the folder name and match "
                            "[A-Za-z0-9_-], at most 50 characters")
        width, height = page.get("width", 0), page.get("height", 0)
        filters = {f.get("name") for f in page.get("filterConfig", {}).get("filters", [])}
        if page.get("pageBinding"):
            bindings.append(page["pageBinding"].get("name"))
            for param in page["pageBinding"].get("parameters", []):
                if param.get("boundFilter") and param["boundFilter"] not in filters:
                    problems.append(f"{rel(page_path)}: pageBinding parameter binds missing filter "
                                    f"{param['boundFilter']}")
        targets = [(page_path, page)]
        boxes = []
        visual_names = set()
        visuals_dir = pages_dir / folder / "visuals"
        for vdir in sorted(visuals_dir.iterdir()) if visuals_dir.is_dir() else []:
            vpath = vdir / "visual.json"
            visual = docs_json.get(vpath)
            if not isinstance(visual, dict):
                problems.append(f"{rel(vdir)}: no visual.json")
                continue
            n_visuals += 1
            targets.append((vpath, visual))
            name = visual.get("name")
            visual_names.add(name)
            if name != vdir.name or not NAME_RE.match(vdir.name):
                problems.append(f"{rel(vpath)}: name {name!r} must equal the folder name and match [A-Za-z0-9_-]")
            pos = visual.get("position", {})
            x, y, w, h = (pos.get(k, 0) for k in ("x", "y", "width", "height"))
            if x < 0 or y < 0 or x + w > width or y + h > height:
                problems.append(f"{rel(vpath)}: box ({x}, {y}, {w}, {h}) is outside the {width} x {height} page")
            if not HEADER_VISUAL.search(name or "") and (w < MIN_W or h < MIN_H):
                problems.append(f"{rel(vpath)}: {w} x {h} px is below the {MIN_W} x {MIN_H} px minimum")
            boxes.append((name, x, y, w, h))
            body = visual.get("visual", {})
            qrefs = []
            for role, state in body.get("query", {}).get("queryState", {}).items():
                for proj in state.get("projections", []):
                    qrefs.append(proj.get("queryRef"))
                    expected = expected_query_ref(proj.get("field", {}))
                    if expected and proj.get("queryRef") != expected:
                        problems.append(f"{rel(vpath)}: {role} queryRef {proj.get('queryRef')!r}, expected "
                                        f"{expected!r}")
            if len(set(qrefs)) != len(qrefs):
                problems.append(f"{rel(vpath)}: queryRef values are not unique")
            for meta in selectors(body):
                if meta not in qrefs:
                    problems.append(f"{rel(vpath)}: formatting selector points at {meta!r}, not a field of the visual")
            vtype = body.get("visualType")
            if vtype not in ("textbox", "slicer"):
                title = body.get("visualContainerObjects", {}).get("title", [{}])[0].get("properties", {})
                shown = title.get("show", {}).get("expr", {}).get("Literal", {}).get("Value") == "true"
                if not HEADER_VISUAL.search(name or "") and not (shown and title.get("text")):
                    problems.append(f"{rel(vpath)}: content visual has no title")
        for a in range(len(boxes)):
            for b in range(a + 1, len(boxes)):
                na, xa, ya, wa, ha = boxes[a]
                nb, xb, yb, wb, hb = boxes[b]
                if xa < xb + wb and xb < xa + wa and ya < yb + hb and yb < ya + ha:
                    problems.append(f"{folder}: visuals {na} and {nb} overlap")
        for inter in page.get("visualInteractions", []):
            for end in ("source", "target"):
                if inter.get(end) not in visual_names:
                    problems.append(f"{rel(page_path)}: visual interaction {end} {inter.get(end)!r} is not on the page")
        for path, doc in targets:
            for kind, entity, prop, where in field_refs(doc):
                n_refs += 1
                if kind == "Column":
                    ok = prop in columns.get(entity, {})
                elif kind == "Measure":
                    ok = prop in measures and measures[prop][0] == entity
                else:
                    hierarchy, _, level = prop.partition("/")
                    ok = level in hierarchies.get((entity, hierarchy), [])
                if not ok:
                    problems.append(f"{rel(path)}: {kind} {entity}[{prop}] at {where} is not in model.bim")
    if len(set(bindings)) != len(bindings):
        problems.append("pageBinding names are not unique across the report")

    stats = {"files": len(docs_json), "validated": validated, "schemas": len({id(d) for d in schemas.values()}),
             "tables": len(tables), "csv_columns": typed_columns, "measures": len(measures),
             "relationships": len(model_rels), "pages": len(folders), "visuals": n_visuals, "field_refs": n_refs}
    return problems, warnings, stats


def main(argv: list[str] | None = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    project = pathlib.Path(argv[0]).resolve() if argv else ROOT / "powerbi"
    problems, warnings, stats = run_checks(project, ROOT)
    for w in warnings:
        print(f"warning: {w}")
    if problems:
        print(f"PBIP checks FAILED ({len(problems)} problems):")
        print("\n".join(f"  - {p}" for p in problems))
        return 1
    print(f"PBIP checks passed: {stats['validated']} files schema-valid against {stats['schemas']} vendored schemas; "
          f"{stats['tables']} tables, {stats['csv_columns']} typed CSV columns, {stats['measures']} measures, "
          f"{stats['relationships']} relationships, {stats['pages']} pages, {stats['visuals']} visuals, "
          f"{stats['field_refs']} field references resolved")
    return 0


if __name__ == "__main__":
    sys.exit(main())
